#include <limits>
#include <string>
#include <iostream>

int main() {
    // Check built-in type
    if (std::numeric_limits<int>::is_specialized) {
        std::cout << "Int Max: " << std::numeric_limits<int>::max() << "\n";
    }

    // Check non-numeric type
    bool specialized_string = std::numeric_limits<std::string>::is_specialized;
    std::cout << "String Specialized: " << std::boolalpha << specialized_string << "\n";

    // Check signed property
    std::cout << "Char is signed: " << std::boolalpha 
              << std::numeric_limits<char>::is_signed << "\n";
}
